namespace {
using Category = BuildSizeAnalyzerPanel::Category;
constexpr std::uint64_t kMiB = 1024ull * 1024ull;

std::string Lower(std::string value) { std::transform(value.begin(), value.end(), value.begin(), [](unsigned char c) { return static_cast<char>(std::tolower(c)); }); return value; }
std::string Normalized(std::string value) { std::replace(value.begin(), value.end(), '\\', '/'); value = Lower(value); while (value.rfind("./", 0) == 0) value.erase(0, 2); if (value.rfind("/game/", 0) == 0) value.erase(0, 6); if (value.rfind("content/", 0) == 0) value.erase(0, 8); return value; }
const char* CategoryName(Category category) { switch (category) {
case Category::Runtime:return "Runtime"; case Category::Scenes:return "Scenes / Worlds"; case Category::Meshes:return "Meshes"; case Category::Animation:return "Animation"; case Category::Textures:return "Textures"; case Category::MaterialsShaders:return "Materials / Shaders"; case Category::Audio:return "Audio"; case Category::Scripts:return "Scripts"; case Category::Vfx:return "VFX"; case Category::UiLocalization:return "UI / Localization"; case Category::Configuration:return "Configuration"; case Category::Other:return "Other"; case Category::Count:break; } return "Other"; }
Category Categorize(const std::filesystem::path& path) {
    const std::string ext = Lower(path.extension().string());
    if (ext==".exe"||ext==".dll"||ext==".pdb"||ext==".so"||ext==".dylib") return Category::Runtime;
    if (ext==".scene"||ext==".3dgworld") return Category::Scenes;
    if (ext==".3dgmesh"||ext==".3dgskmesh"||ext==".fbx"||ext==".obj"||ext==".gltf"||ext==".glb") return Category::Meshes;
    if (ext==".3dganim"||ext==".3dgclip"||ext==".3dggraph"||ext==".3dgskel"||ext==".3dgretarget"||ext==".3dgragdoll"||ext==".3dgpose") return Category::Animation;
    if (ext==".3dgtex"||ext==".png"||ext==".jpg"||ext==".jpeg"||ext==".tga"||ext==".dds"||ext==".hdr"||ext==".ktx"||ext==".ktx2") return Category::Textures;
    if (ext==".3dgmat"||ext==".3dgshader"||ext==".glsl"||ext==".vert"||ext==".frag"||ext==".spv") return Category::MaterialsShaders;
    if (ext==".wav"||ext==".ogg"||ext==".mp3"||ext==".flac"||ext==".3dgaudio") return Category::Audio;
    if (ext==".lua"||ext==".cpp"||ext==".h"||ext==".hpp"||ext==".3dgvs") return Category::Scripts;
    if (ext==".particle"||ext==".3dgparticle"||ext==".3dgfx") return Category::Vfx;
    if (ext==".hud"||ext==".3dgloc"||ext==".ttf"||ext==".otf") return Category::UiLocalization;
    if (ext==".cfg"||ext==".ini"||ext==".json"||ext==".toml"||ext==".3dgmanifest"||ext==".3dgdb"||ext==".3dgproject") return Category::Configuration;
    return Category::Other;
}
double CompressionRatio(const std::filesystem::path& path) {
    const std::string ext=Lower(path.extension().string());
    if(ext==".png"||ext==".jpg"||ext==".jpeg"||ext==".dds"||ext==".ktx"||ext==".ktx2"||ext==".ogg"||ext==".mp3"||ext==".zip")return 0.98;
    if(ext==".txt"||ext==".json"||ext==".cfg"||ext==".ini"||ext==".lua"||ext==".scene"||ext==".3dgmanifest")return 0.32;
    if(ext==".exe"||ext==".dll"||ext==".pdb")return 0.68;
    return 0.72;
}
std::uint64_t HashFile(const std::filesystem::path& path) { std::ifstream in(path,std::ios::binary); if(!in)return 0; std::uint64_t hash=1469598103934665603ull; char buffer[65536]; while(in){in.read(buffer,sizeof(buffer));const auto n=in.gcount();for(std::streamsize i=0;i<n;++i){hash^=static_cast<unsigned char>(buffer[i]);hash*=1099511628211ull;}}return hash; }
std::string FormatBytes(std::uint64_t bytes) { std::ostringstream out; out<<std::fixed<<std::setprecision(bytes>=kMiB?2:1); if(bytes>=1024ull*kMiB)out<<static_cast<double>(bytes)/(1024.0*kMiB)<<" GiB";else if(bytes>=kMiB)out<<static_cast<double>(bytes)/kMiB<<" MiB";else if(bytes>=1024)out<<static_cast<double>(bytes)/1024.0<<" KiB";else out<<bytes<<" B";return out.str(); }
std::string Timestamp(){const auto now=std::chrono::system_clock::now();const std::time_t time=std::chrono::system_clock::to_time_t(now);std::tm local{};
#if defined(_WIN32)
localtime_s(&local,&time);
#else
localtime_r(&time,&local);
#endif
std::ostringstream out;out<<std::put_time(&local,"%Y%m%d-%H%M%S");return out.str();}
bool AssetLike(const std::filesystem::path& path){return Categorize(path)!=Category::Runtime&&Categorize(path)!=Category::Configuration&&path.filename()!="AssetRegistry.3dgdb";}
void Accumulate(BuildSizeAnalyzerPanel::ScanResult& result){result.categories={};result.rawBytes=result.compressedBytes=result.unusedBytes=result.duplicateBytes=0;std::unordered_set<int> duplicateRepresentatives;for(const auto& file:result.files){auto& c=result.categories[static_cast<std::size_t>(file.category)];c.files++;c.rawBytes+=file.rawBytes;c.compressedBytes+=file.compressedBytes;result.rawBytes+=file.rawBytes;result.compressedBytes+=file.compressedBytes;if(file.unused){c.unusedBytes+=file.rawBytes;result.unusedBytes+=file.rawBytes;}if(file.duplicateGroup>0&&!duplicateRepresentatives.insert(file.duplicateGroup).second){c.duplicateBytes+=file.rawBytes;result.duplicateBytes+=file.rawBytes;}}}
std::uint16_t U16(const std::vector<unsigned char>& d,std::size_t p){return static_cast<std::uint16_t>(d[p]|(d[p+1]<<8));}
std::uint32_t U32(const std::vector<unsigned char>& d,std::size_t p){return static_cast<std::uint32_t>(d[p])|(static_cast<std::uint32_t>(d[p+1])<<8)|(static_cast<std::uint32_t>(d[p+2])<<16)|(static_cast<std::uint32_t>(d[p+3])<<24);}
}

BuildSizeAnalyzerPanel::~BuildSizeAnalyzerPanel(){if(m_future.valid())m_future.wait();}
void BuildSizeAnalyzerPanel::SetTarget(const std::filesystem::path& path){const std::string text=path.string();std::memset(m_target.data(),0,m_target.size());std::snprintf(m_target.data(),m_target.size(),"%s",text.c_str());}

BuildSizeAnalyzerPanel::ScanResult BuildSizeAnalyzerPanel::ScanFolder(const std::filesystem::path& root,const std::filesystem::path& contentRoot,std::vector<std::string> registryUnused){
    ScanResult result;std::error_code ec;if(!std::filesystem::is_directory(root,ec)){result.error="The selected analysis folder does not exist.";return result;}
    std::unordered_set<std::string> manifestPaths;for(std::filesystem::recursive_directory_iterator it(root,std::filesystem::directory_options::skip_permission_denied,ec),end;!ec&&it!=end;it.increment(ec)){if(!it->is_regular_file(ec)||Lower(it->path().filename().string()).find("manifest")==std::string::npos)continue;std::ifstream in(it->path());std::string tag;while(in>>tag){if(tag=="scene"){std::string id,path;in>>id>>std::quoted(path);manifestPaths.insert(Normalized(path));}else if(tag=="asset"){std::string id,path;unsigned type=0;std::uint64_t size=0,hash=0;in>>id>>type>>std::quoted(path)>>size>>hash;manifestPaths.insert(Normalized(path));}else{std::string line;std::getline(in,line);}}}
    result.manifestFiles=manifestPaths.size();std::unordered_set<std::string> unused(registryUnused.begin(),registryUnused.end());
    std::filesystem::path effectiveContent=contentRoot;const auto nested=root/"Content";if(std::filesystem::is_directory(nested,ec))effectiveContent=nested;else if(!std::filesystem::is_directory(effectiveContent,ec)||root==contentRoot)effectiveContent=root;
    for(std::filesystem::recursive_directory_iterator it(root,std::filesystem::directory_options::skip_permission_denied,ec),end;!ec&&it!=end;it.increment(ec)){if(!it->is_regular_file(ec))continue;FileEntry file;file.path=std::filesystem::relative(it->path(),root,ec).generic_string();if(ec){ec.clear();file.path=it->path().filename().generic_string();}file.rawBytes=it->file_size(ec);if(ec){ec.clear();continue;}file.compressedBytes=static_cast<std::uint64_t>(file.rawBytes*CompressionRatio(it->path()));file.category=Categorize(it->path());file.fingerprint=HashFile(it->path());std::string contentRelative;const auto absolute=std::filesystem::absolute(it->path(),ec).lexically_normal();const auto contentAbsolute=std::filesystem::absolute(effectiveContent,ec).lexically_normal();const auto rel=std::filesystem::relative(absolute,contentAbsolute,ec);if(!ec&&!rel.empty()&&*rel.begin()!="..")contentRelative=Normalized(rel.generic_string());else ec.clear();if(!contentRelative.empty()){if(!manifestPaths.empty())file.unused=AssetLike(it->path())&&manifestPaths.find(contentRelative)==manifestPaths.end()&&Lower(it->path().extension().string())!=".lua";else file.unused=unused.find(contentRelative)!=unused.end();}result.files.push_back(std::move(file));}
    if(ec)result.error="The scan stopped early: "+ec.message();
    std::unordered_map<std::uint64_t,std::vector<std::size_t>> bySize;for(std::size_t i=0;i<result.files.size();++i)if(result.files[i].rawBytes>0)bySize[result.files[i].rawBytes].push_back(i);int group=0;for(auto& [size,indices]:bySize){if(indices.size()<2)continue;std::unordered_map<std::uint64_t,std::vector<std::size_t>> byHash;for(auto i:indices)byHash[result.files[i].fingerprint].push_back(i);for(auto& [hash,matches]:byHash)if(hash&&matches.size()>1){++group;for(auto i:matches)result.files[i].duplicateGroup=group;}}
    result.duplicateGroups=group;result.unusedAvailable=!manifestPaths.empty()||!registryUnused.empty();Accumulate(result);return result;
}

BuildSizeAnalyzerPanel::ScanResult BuildSizeAnalyzerPanel::ScanZip(const std::filesystem::path& path){
    ScanResult result;result.compressedIsEstimate=false;std::ifstream in(path,std::ios::binary);if(!in){result.error="The selected package could not be opened.";return result;}in.seekg(0,std::ios::end);const auto length=in.tellg();if(length<=0){result.error="The selected package is empty.";return result;}const std::size_t tail=static_cast<std::size_t>(std::min<std::streamoff>(length,65557));std::vector<unsigned char> data(static_cast<std::size_t>(length));in.seekg(0);in.read(reinterpret_cast<char*>(data.data()),static_cast<std::streamsize>(data.size()));std::size_t eocd=data.size();for(std::size_t p=data.size()-std::min(data.size(),tail);p+4<=data.size();++p)if(U32(data,p)==0x06054b50u)eocd=p;if(eocd==data.size()||eocd+22>data.size()){result.error="This ZIP package has no readable central directory.";return result;}const auto count=U16(data,eocd+10);std::size_t p=U32(data,eocd+16);int group=0;std::unordered_map<std::uint64_t,std::vector<std::size_t>> duplicates;for(std::uint16_t i=0;i<count&&p+46<=data.size();++i){if(U32(data,p)!=0x02014b50u){result.error="The ZIP central directory is damaged or unsupported.";break;}const auto compressed=U32(data,p+20),raw=U32(data,p+24);const auto nameLength=U16(data,p+28),extraLength=U16(data,p+30),commentLength=U16(data,p+32);if(compressed==0xffffffffu||raw==0xffffffffu){result.error="ZIP64 packages are not supported by this analyzer yet.";break;}if(p+46+nameLength>data.size())break;std::string name(reinterpret_cast<const char*>(data.data()+p+46),nameLength);if(!name.empty()&&name.back()!='/'){FileEntry file;file.path=name;file.rawBytes=raw;file.compressedBytes=compressed;file.fingerprint=(static_cast<std::uint64_t>(U32(data,p+16))<<32)|raw;file.category=Categorize(name);duplicates[file.fingerprint].push_back(result.files.size());result.files.push_back(std::move(file));}p+=46+nameLength+extraLength+commentLength;}
    for(auto& [fingerprint,matches]:duplicates)if(fingerprint&&matches.size()>1){++group;for(auto i:matches)result.files[i].duplicateGroup=group;}result.duplicateGroups=group;Accumulate(result);return result;
}

void BuildSizeAnalyzerPanel::StartScan(const std::filesystem::path& contentRoot,const engine::AssetRegistry& registry){
    if(m_running)return;const std::filesystem::path target(m_target.data());if(target.empty()){m_status="Choose something to analyze first.";return;}std::vector<std::string> unused;for(const auto& entry:registry.Entries())if(entry.type!=engine::AssetType::Scene&&entry.type!=engine::AssetType::World&&registry.Referencers(entry.id).empty())unused.push_back(Normalized(entry.virtualPath));m_running=true;m_status="Analyzing build files...";m_result={};m_future=std::async(std::launch::async,[target,contentRoot,unused=std::move(unused)](){if(Lower(target.extension().string())==".zip")return ScanZip(target);return ScanFolder(target,contentRoot,unused);});
}
void BuildSizeAnalyzerPanel::Poll(){if(!m_running||!m_future.valid()||m_future.wait_for(std::chrono::milliseconds(0))!=std::future_status::ready)return;try{m_result=m_future.get();if(!m_result.unusedAvailable)m_onlyUnused=false;m_status=m_result.error.empty()?std::to_string(m_result.files.size())+" files analyzed.":m_result.error;}catch(const std::exception& e){m_status=std::string("Analysis failed: ")+e.what();}m_running=false;}

void BuildSizeAnalyzerPanel::ExportReport(bool csv){
    if(m_result.files.empty())return;std::error_code ec;const auto folder=m_projectRoot/"Saved"/"Reports";std::filesystem::create_directories(folder,ec);if(ec){m_status="Could not create the report folder: "+ec.message();return;}const auto path=folder/("BuildSize-"+Timestamp()+(csv?".csv":".txt"));std::ofstream out(path);if(!out){m_status="Could not write the build-size report.";return;}if(csv){out<<"Path,Category,Raw Bytes,Compressed Bytes,Unused,Duplicate Group\n";for(const auto& f:m_result.files)out<<std::quoted(f.path)<<','<<std::quoted(CategoryName(f.category))<<','<<f.rawBytes<<','<<f.compressedBytes<<','<<(f.unused?"yes":"no")<<','<<f.duplicateGroup<<'\n';}else{out<<"3DG Build Size Report\nTarget: "<<m_target.data()<<"\nRaw size: "<<FormatBytes(m_result.rawBytes)<<"\n"<<(m_result.compressedIsEstimate?"Estimated compressed: ":"Compressed: ")<<FormatBytes(m_result.compressedBytes)<<"\nUnused: "<<FormatBytes(m_result.unusedBytes)<<"\nDuplicate copies: "<<FormatBytes(m_result.duplicateBytes)<<"\n\nCategory\tFiles\tRaw\tCompressed\tBudget MiB\n";for(std::size_t i=0;i<static_cast<std::size_t>(Category::Count);++i){const auto& c=m_result.categories[i];out<<CategoryName(static_cast<Category>(i))<<'\t'<<c.files<<'\t'<<c.rawBytes<<'\t'<<c.compressedBytes<<'\t'<<m_categoryBudgetMiB[i]<<'\n';}}m_lastReport=path.string();m_status="Report saved: "+m_lastReport;
}

void BuildSizeAnalyzerPanel::Draw(const std::filesystem::path& projectRoot,const std::filesystem::path& contentRoot,const std::filesystem::path& packageOutput,const engine::AssetRegistry& registry,bool* open){
    Poll();m_projectRoot=projectRoot;m_contentRoot=contentRoot;if(!m_initialized){m_initialized=true;std::filesystem::path target;std::error_code ec;if(std::filesystem::is_directory(packageOutput,ec)){std::filesystem::path newest;std::filesystem::file_time_type newestTime{};for(const auto& item:std::filesystem::directory_iterator(packageOutput,ec))if(item.is_regular_file(ec)&&Lower(item.path().extension().string())==".zip"&&item.last_write_time(ec)>=newestTime){newest=item.path();newestTime=item.last_write_time(ec);}else if(item.is_directory(ec)&&item.last_write_time(ec)>=newestTime){newest=item.path();newestTime=item.last_write_time(ec);}target=newest;}if(target.empty()){const auto cooked=projectRoot/"Build"/"Cooked";if(std::filesystem::is_directory(cooked,ec))target=cooked;}if(target.empty())target=contentRoot;SetTarget(target);}
    if(!ImGui::Begin(EditorPanels::Name(EditorPanels::Panel::BuildSizeAnalyzer),open)){ImGui::End();return;}
    ImGui::TextUnformatted("Measure what a packaged build contains and find avoidable size.");ImGui::SetNextItemWidth(-205.0f);ImGui::InputText("##build_size_target",m_target.data(),m_target.size());ImGui::SameLine();if(ImGui::Button("Browse Folder...")){const auto folder=editor::PickFolderDialog("Choose staged or package folder");if(!folder.empty())SetTarget(folder);}ImGui::SameLine();if(ImGui::Button("ZIP...")){const auto file=editor::OpenFileDialog("Choose packaged ZIP","ZIP package","zip");if(!file.empty())SetTarget(file);}if(ImGui::Button("Project Content"))SetTarget(contentRoot);ImGui::SameLine();if(ImGui::Button("Package Output"))SetTarget(packageOutput);ImGui::SameLine();ImGui::BeginDisabled(m_running);if(ImGui::Button("Analyze"))StartScan(contentRoot,registry);ImGui::EndDisabled();if(m_running){ImGui::SameLine();ImGui::TextDisabled("Working...");}ImGui::TextWrapped("%s",m_status.c_str());
    if(!m_result.files.empty()){const float rawMiB=static_cast<float>(m_result.rawBytes)/static_cast<float>(kMiB);const float fraction=m_totalBudgetMiB>0.0f?rawMiB/m_totalBudgetMiB:0.0f;ImGui::SetNextItemWidth(170);ImGui::DragFloat("Total budget (MiB)",&m_totalBudgetMiB,8.0f,1.0f,1048576.0f,"%.0f");ImGui::ProgressBar(std::clamp(fraction,0.0f,1.0f),ImVec2(-1,0),fraction>1.0f?"Over budget":"Build budget");ImGui::Text("Raw: %s   %s: %s   Files: %zu",FormatBytes(m_result.rawBytes).c_str(),m_result.compressedIsEstimate?"Estimated compressed":"Compressed",FormatBytes(m_result.compressedBytes).c_str(),m_result.files.size());ImGui::Text("Unused: %s   Duplicate copies: %s (%d groups)   Manifest entries: %llu",m_result.unusedAvailable?FormatBytes(m_result.unusedBytes).c_str():"not available",FormatBytes(m_result.duplicateBytes).c_str(),m_result.duplicateGroups,static_cast<unsigned long long>(m_result.manifestFiles));
        if(ImGui::CollapsingHeader("Category Budgets",ImGuiTreeNodeFlags_DefaultOpen)&&ImGui::BeginTable("##build_size_categories",6,ImGuiTableFlags_Borders|ImGuiTableFlags_RowBg|ImGuiTableFlags_SizingStretchProp)){ImGui::TableSetupColumn("Category");ImGui::TableSetupColumn("Files");ImGui::TableSetupColumn("Raw");ImGui::TableSetupColumn("Compressed");ImGui::TableSetupColumn("Unused / Duplicate");ImGui::TableSetupColumn("Budget MiB");ImGui::TableHeadersRow();for(std::size_t i=0;i<static_cast<std::size_t>(Category::Count);++i){const auto& c=m_result.categories[i];if(!c.files)continue;ImGui::PushID(static_cast<int>(i));ImGui::TableNextRow();ImGui::TableSetColumnIndex(0);ImGui::TextUnformatted(CategoryName(static_cast<Category>(i)));ImGui::TableSetColumnIndex(1);ImGui::Text("%llu",static_cast<unsigned long long>(c.files));ImGui::TableSetColumnIndex(2);ImGui::TextUnformatted(FormatBytes(c.rawBytes).c_str());ImGui::TableSetColumnIndex(3);ImGui::TextUnformatted(FormatBytes(c.compressedBytes).c_str());ImGui::TableSetColumnIndex(4);ImGui::Text("%s / %s",FormatBytes(c.unusedBytes).c_str(),FormatBytes(c.duplicateBytes).c_str());ImGui::TableSetColumnIndex(5);ImGui::SetNextItemWidth(-1);ImGui::DragFloat("##budget",&m_categoryBudgetMiB[i],1.0f,0.0f,1048576.0f,"%.0f");if(m_categoryBudgetMiB[i]>0.0f&&static_cast<double>(c.rawBytes)/kMiB>m_categoryBudgetMiB[i]){ImGui::SameLine();ImGui::TextColored(ImVec4(1,0.35f,0.2f,1),"Over");}ImGui::PopID();}ImGui::EndTable();}
        ImGui::SeparatorText("Files");ImGui::SetNextItemWidth(220);ImGui::InputTextWithHint("##build_size_filter","Filter path or category",m_filter.data(),m_filter.size());ImGui::SameLine();ImGui::Checkbox("Issues only",&m_onlyIssues);ImGui::SameLine();ImGui::BeginDisabled(!m_result.unusedAvailable);ImGui::Checkbox("Unused",&m_onlyUnused);ImGui::EndDisabled();ImGui::SameLine();ImGui::Checkbox("Duplicates",&m_onlyDuplicates);ImGui::SameLine();const char* sorts[]={"Largest first","Path","Category"};ImGui::SetNextItemWidth(130);ImGui::Combo("##build_size_sort",&m_sort,sorts,3);
        std::vector<const FileEntry*> visible;const std::string filter=Lower(m_filter.data());for(const auto& f:m_result.files){if(m_onlyIssues&&!f.unused&&f.duplicateGroup==0)continue;if(m_onlyUnused&&!f.unused)continue;if(m_onlyDuplicates&&f.duplicateGroup==0)continue;if(!filter.empty()&&Lower(f.path+" "+CategoryName(f.category)).find(filter)==std::string::npos)continue;visible.push_back(&f);}std::sort(visible.begin(),visible.end(),[this](const FileEntry* a,const FileEntry* b){if(m_sort==1)return a->path<b->path;if(m_sort==2)return std::pair(a->category,a->path)<std::pair(b->category,b->path);return a->rawBytes>b->rawBytes;});if(ImGui::BeginTable("##build_size_files",6,ImGuiTableFlags_Borders|ImGuiTableFlags_RowBg|ImGuiTableFlags_ScrollY|ImGuiTableFlags_SizingStretchProp,ImVec2(0,260))){ImGui::TableSetupScrollFreeze(0,1);ImGui::TableSetupColumn("Path");ImGui::TableSetupColumn("Category");ImGui::TableSetupColumn("Raw");ImGui::TableSetupColumn(m_result.compressedIsEstimate?"Est. packed":"Packed");ImGui::TableSetupColumn("Unused");ImGui::TableSetupColumn("Duplicate");ImGui::TableHeadersRow();for(const auto* f:visible){ImGui::TableNextRow();ImGui::TableSetColumnIndex(0);ImGui::TextUnformatted(f->path.c_str());ImGui::TableSetColumnIndex(1);ImGui::TextUnformatted(CategoryName(f->category));ImGui::TableSetColumnIndex(2);ImGui::TextUnformatted(FormatBytes(f->rawBytes).c_str());ImGui::TableSetColumnIndex(3);ImGui::TextUnformatted(FormatBytes(f->compressedBytes).c_str());ImGui::TableSetColumnIndex(4);if(f->unused)ImGui::TextColored(ImVec4(1,0.65f,0.2f,1),"Yes");else ImGui::TextUnformatted("-");ImGui::TableSetColumnIndex(5);if(f->duplicateGroup)ImGui::Text("Group %d",f->duplicateGroup);else ImGui::TextUnformatted("-");}ImGui::EndTable();}
        if(ImGui::Button("Export Text Report"))ExportReport(false);ImGui::SameLine();if(ImGui::Button("Export CSV"))ExportReport(true);if(!m_lastReport.empty()){ImGui::SameLine();ImGui::TextDisabled("%s",m_lastReport.c_str());}
    }ImGui::End();
}
